def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    S = data[1]

    if N == 0:
        print(0)
        return

    count = 1
    for i in range(1, N):
        if S[i] != S[i-1]:
            count += 1
    print(count)

if __name__ == "__main__":
    main()

