import sys

def main():
    n = int(sys.stdin.readline())
    s = set()
    for _ in range(n):
        num = int(sys.stdin.readline())
        if num in s:
            s.remove(num)
        else:
            s.add(num)
    print(len(s))

if __name__ == "__main__":
    main()

